function minimumTime(power) {
  const n = power.length;
  const full = 1 << n;
  const dp = new Array(full).fill(Infinity);
  dp[0] = 0;
  for (let mask = 0; mask < full; mask++) {
    let gain = 1;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) {
        gain++;
      }
    }
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) {
        continue;
      }
      const next = mask | (1 << i);
      const days = Math.ceil(power[i] / gain);
      dp[next] = Math.min(dp[next], dp[mask] + days);
    }
  }
  return dp[full - 1];
}

