function minimumTime(power) {
  // Try every kill order; equal powers are interchangeable, so each value is tried once per position.
  let best = Infinity;
  const used = power.map(() => false);
  const walk = (count, total) => {
    if (total >= best) return;
    if (count === power.length) { best = total; return; }
    const tried = new Set();
    for (let i = 0; i < power.length; i++) {
      if (used[i] || tried.has(power[i])) continue;
      tried.add(power[i]);
      used[i] = true;
      const gain = count + 1;
      let mana = 0, days = 0;
      if (power[i] <= 1000) { while (mana < power[i]) { mana += gain; days++; } }
      else days = Math.floor((power[i] - 1) / gain) + 1;
      walk(count + 1, total + days);
      used[i] = false;
    }
  };
  walk(0, 0);
  return best;
}

