function generate(rand, size) {
  if (size === 'large') {
    const n = 15 + Math.floor(rand() * 3);
    return [Array.from({ length: n }, () => 1 + Math.floor(rand() * 1000000000))];
  }
  const n = 1 + Math.floor(rand() * 7);
  const style = rand();
  const top = style < 0.4 ? 10 : style < 0.8 ? 60 : 1000000000;
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
